{
  "objective": "Build a dependency-free command-line utility that reads one local UTF-8 text file and writes deterministic word and line counts.",
  "requirements": [
    {
      "id": "R1",
      "source": "User request: dependency-free command-line utility",
      "requirement": "Use Python 3 and its standard library exclusively, with no third-party packages."
    },
    {
      "id": "R2",
      "source": "User request: reads a local UTF-8 text file",
      "requirement": "Accept exactly one positional file path, read it locally, and reject invalid UTF-8 without emitting partial counts."
    },
    {
      "id": "R3",
      "source": "User request: deterministic word and line counts",
      "requirement": "Count words as maximal nonempty runs separated by ASCII whitespace: space, tab, LF, CR, form feed, and vertical tab. Treat other Unicode characters as word content."
    },
    {
      "id": "R4",
      "source": "User request: deterministic word and line counts",
      "requirement": "Count LF, CRLF, and lone CR as line terminators, treating CRLF as one terminator. Count a final unterminated nonempty segment as one line. An empty file has zero lines."
    },
    {
      "id": "R5",
      "source": "User request: writes deterministic word and line counts",
      "requirement": "Write one UTF-8 JSON object to standard output, with keys ordered as words then lines, integer values, no spaces, and one trailing LF."
    },
    {
      "id": "R6",
      "source": "User request: independent verification and review requirements",
      "requirement": "Validate results using manually derived expectations and require a reviewer other than the implementer to inspect semantics, failure handling, and dependency use."
    }
  ],
  "assumptions": [
    "Python 3 is already installed; dependency-free means no additional packages.",
    "Standard output is the requested output destination.",
    "The input is a regular file that fits in memory and remains unchanged during reading.",
    "A leading UTF-8 byte-order mark is accepted and removed before counting; any later U+FEFF is ordinary content.",
    "Only counts, not file contents or paths, appear in successful output.",
    "The word and line definitions above are proposed product decisions because the user did not specify boundary semantics."
  ],
  "acceptance": [
    {
      "id": "A1",
      "requirements": ["R2", "R3", "R4", "R5"],
      "criterion": "An empty file produces words=0 and lines=0 and exits with status 0."
    },
    {
      "id": "A2",
      "requirements": ["R3", "R4"],
      "criterion": "A file containing alpha, one space, and beta without a terminator produces words=2 and lines=1."
    },
    {
      "id": "A3",
      "requirements": ["R4"],
      "criterion": "A file containing alpha followed by CRLF, beta followed by lone CR, and gamma followed by LF produces words=3 and lines=3."
    },
    {
      "id": "A4",
      "requirements": ["R3", "R4"],
      "criterion": "Two consecutive LF characters produce words=0 and lines=2."
    },
    {
      "id": "A5",
      "requirements": ["R3"],
      "criterion": "Two nonempty strings separated only by a nonbreaking space count as one word; replacing that separator with a tab yields two words."
    },
    {
      "id": "A6",
      "requirements": ["R2"],
      "criterion": "Invalid UTF-8, a missing file, an unreadable file, or a directory input produces no standard output, a concise standard-error diagnostic, and exit status 1."
    },
    {
      "id": "A7",
      "requirements": ["R2"],
      "criterion": "Zero or multiple positional paths produces no standard output, a usage diagnostic on standard error, and exit status 2."
    },
    {
      "id": "A8",
      "requirements": ["R5"],
      "criterion": "Repeated runs on unchanged input produce byte-identical output matching the required key order, whitespace, encoding, and trailing LF."
    },
    {
      "id": "A9",
      "requirements": ["R1", "R6"],
      "criterion": "All checks pass using only the designated Python runtime and its standard library."
    }
  ],
  "assignments": [
    {
      "id": "implementation",
      "scope": "Implement decoding, counting, command-line validation, output formatting, and concise usage documentation.",
      "allowed_paths": ["wordcount.py", "README.md"],
      "interfaces": [
        "Counting interface: decoded text in, a pair of nonnegative integers ordered words then lines out.",
        "CLI interface: exactly one positional local file path; standard output, standard error, and exit statuses follow the acceptance criteria."
      ],
      "dependencies": ["Approved counting and output contract in R2 through R5"]
    },
    {
      "id": "independent_validation",
      "scope": "Create standard-library tests with independently derived expectations and review the implementation without editing implementation files.",
      "allowed_paths": ["tests/test_wordcount.py", "tests/fixtures/", "review.md"],
      "interfaces": [
        "Exercise the public CLI and capture output bytes, diagnostics, and exit status.",
        "Record review findings with requirement identifiers and resolution status."
      ],
      "dependencies": [
        "R1 through R6 for independent test design",
        "Implementation assignment for final execution and review"
      ]
    }
  ],
  "dependencies": {
    "runtime": ["Python 3 standard library"],
    "external_packages": [],
    "sequencing": [
      "Fix the behavioral contract before implementation.",
      "Develop independent expected results from the contract while implementation proceeds.",
      "Complete integration before final verification and review."
    ]
  },
  "integration_strategy": "Keep production behavior in one module. Integrate decoding and counting first, then connect argument validation and deterministic serialization. Add independently authored CLI tests without overlapping production ownership. Resolve discrepancies against the documented contract and rerun affected checks before final review.",
  "verification_requirements": [
    "Derive expected counts manually from explicit character sequences; do not use the production counting function as the test oracle.",
    "Cover every acceptance criterion with standard-library tests that exercise the public CLI.",
    "Include leading BOM, BOM-only input, punctuation, repeated whitespace, multilingual text, trailing terminators, and paths containing spaces.",
    "Assert exact successful output bytes and empty standard output on failure.",
    "Check unreadable-file behavior in an environment that enforces file permissions; record a limitation if elevated privileges prevent that check."
  ],
  "review_requirements": [
    "A reviewer other than the implementer must inspect requirement-to-test coverage and independently check representative expected counts.",
    "Confirm strict UTF-8 decoding, leading-BOM handling, CRLF treatment, and ASCII-whitespace semantics match the contract.",
    "Confirm imports use only the standard library and the utility performs no writes to input files.",
    "Confirm documentation states runtime prerequisites, counting rules, output format, and exit statuses.",
    "Resolve correctness findings and record verification results before accepting the utility."
  ]
}
